create or replace function public.enterprise_reply_service_request(p_request_id uuid,p_message text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_request public.enterprise_service_requests%rowtype; v_event uuid; begin if v_actor is null then raise exception 'authentication_required'; end if; if coalesce(trim(p_message),'')='' then raise exception 'message_required'; end if; select * into v_request from public.enterprise_service_requests where id=p_request_id; if not found then raise exception 'request_not_found'; end if; if not (v_request.requester_user_id=v_actor or (v_request.enterprise_id is not null and private.is_enterprise_user(v_request.enterprise_id))) then raise exception 'insufficient_privilege'; end if; insert into public.enterprise_service_request_events(request_id,event_type,status,note,visible_to_enterprise,created_by) values(p_request_id,'enterprise_reply',v_request.status,p_message,true,v_actor) returning id into v_event; update public.enterprise_service_requests set updated_at=now() where id=p_request_id; insert into public.audit_logs(actor_user_id,actor_role,action,subject_type,subject_id,note) values(v_actor,'enterprise_user','enterprise_case_reply','enterprise_service_request',p_request_id::text,'enterprise reply added'); return v_event; end; $$; revoke all on function public.enterprise_reply_service_request(uuid,text) from public,anon; grant execute on function public.enterprise_reply_service_request(uuid,text) to authenticated; create index if not exists idx_enterprise_service_request_events_request_created on public.enterprise_service_request_events(request_id,created_at);
